"""Тесты переходов: сгенерированные правила против семантики согласованной модели.

Ожидаемые состояния вычислены генератором по BehavioralModel 1.0 (proveryalka.behavior.step)
для этой версии. Тесты проверяют перечисленные состояния и не доказывают соответствие
во всех состояниях."""
import json
from pathlib import Path

import pytest

from app import engine


TABLE = json.loads((Path(__file__).parent / "data" / "conformance.json").read_text(encoding="utf-8"))
ROWS = TABLE["rows"]


# Approve «Согласовать» — R2
# Исходное состояние — начальное
def test_Approve_applies_effects_and_keeps_other_variables():
    before = {'status': 'Created', 'approved': False, 'cancelled': False}
    after = engine.apply(before, 'Approve')
    assert after == {'status': 'Approved', 'approved': True, 'cancelled': False}
    kept = ('cancelled',)
    assert {name: after[name] for name in kept} == {name: before[name] for name in kept}
    assert before == {'status': 'Created', 'approved': False, 'cancelled': False}


def test_Approve_rejected_when_guard_is_false():
    state = {'status': 'Approved', 'approved': True, 'cancelled': False}
    with pytest.raises(engine.TransitionNotEnabled):
        engine.apply(state, 'Approve')
    assert engine.check_state(state) == state


# Cancel «Отменить» — R3
# Исходное состояние достигается из начального: Approve
def test_Cancel_applies_effects_and_keeps_other_variables():
    before = {'status': 'Approved', 'approved': True, 'cancelled': False}
    after = engine.apply(before, 'Cancel')
    assert after == {'status': 'Cancelled', 'approved': False, 'cancelled': True}
    assert before == {'status': 'Approved', 'approved': True, 'cancelled': False}


def test_Cancel_rejected_when_guard_is_false():
    state = {'status': 'Cancelled', 'approved': False, 'cancelled': True}
    with pytest.raises(engine.TransitionNotEnabled):
        engine.apply(state, 'Cancel')
    assert engine.check_state(state) == state


# Execute «Исполнить» — R4
# Исходное состояние достигается из начального: Approve
def test_Execute_applies_effects_and_keeps_other_variables():
    before = {'status': 'Approved', 'approved': True, 'cancelled': False}
    after = engine.apply(before, 'Execute')
    assert after == {'status': 'Executed', 'approved': True, 'cancelled': False}
    kept = ('approved', 'cancelled')
    assert {name: after[name] for name in kept} == {name: before[name] for name in kept}
    assert before == {'status': 'Approved', 'approved': True, 'cancelled': False}


def test_Execute_rejected_when_guard_is_false():
    state = {'status': 'Created', 'approved': False, 'cancelled': False}
    with pytest.raises(engine.TransitionNotEnabled):
        engine.apply(state, 'Execute')
    assert engine.check_state(state) == state


@pytest.mark.parametrize("row", ROWS, ids=[row["id"] for row in ROWS])
def test_conformance_table(row):
    if row["outcome"] == "applied":
        assert engine.apply(row["state"], row["transition"]) == row["next"]
        return
    expected = engine.TransitionNotEnabled if row["outcome"] == "not_enabled" else engine.EffectOutOfDomain
    with pytest.raises(expected):
        engine.apply(row["state"], row["transition"])


def test_unknown_transition_is_rejected():
    with pytest.raises(engine.UnknownTransition):
        engine.apply(engine.initial_state(), '__unknown__')

